232	     1	/**
233	     2	 * @module app/_lib/storage
234	     3	 *
235	     4	 * What this BROWSER remembers (U5b): the ids of its own chats (newest first) and the
236	     5	 * alerts it dismissed. Nothing sensitive: the chats live on the server. US units only (D126).
237	     6	 */
238	     7	import { REMEMBERED_CHATS_LIMIT } from "@/core/agent/config";
239	     8	
240	     9	const SESSIONS_KEY = "sneakoscope.sessions";
241	    10	/** How many past chats the side nav remembers (the sessions API accepts the same number). */
242	    11	const MAX_SESSIONS = REMEMBERED_CHATS_LIMIT;
243	    12	
244	    13	/** True when running in a browser with localStorage available. */
245	    14	const hasStorage = () => typeof window !== "undefined" && !!window.localStorage;
246	    15	
247	    16	/** @returns ids of this browser's chats, newest first. */
248	    17	export function loadSessionIds(): string[] {
249	    18	  if (!hasStorage()) return [];
250	    19	  try {
251	    20	    const parsed: unknown = JSON.parse(window.localStorage.getItem(SESSIONS_KEY) ?? "[]");
252	    21	    return Array.isArray(parsed) ? parsed.filter((id): id is string => typeof id === "string") : [];
253	    22	  } catch {
254	    23	    return [];
255	    24	  }
256	    25	}
257	    26	
258	    27	/**
259	    28	 * Remembers a chat id (moves it to the top).
260	    29	 * @param id - session id.
261	    30	 * @returns the updated list.
262	    31	 */
263	    32	export function rememberSession(id: string): string[] {
264	    33	  const ids = [id, ...loadSessionIds().filter((existing) => existing !== id)].slice(0, MAX_SESSIONS);
265	    34	  if (hasStorage()) window.localStorage.setItem(SESSIONS_KEY, JSON.stringify(ids));
266	    35	  notify();
267	    36	  return ids;
268	    37	}
269	    38	
270	    39	/** Fired in this tab when we change stored values (the "storage" event only fires in OTHER tabs). */
271	    40	const CHANGE_EVENT = "sneakoscope-storage";
272	    41	
273	    42	/** Tells subscribers in this tab that stored values changed. */
274	    43	function notify(): void {
275	    44	  if (typeof window !== "undefined") window.dispatchEvent(new Event(CHANGE_EVENT));
276	    45	}
277	    46	
278	    47	/**
279	    48	 * Subscribes to stored-value changes (this tab and other tabs), for useSyncExternalStore.
280	    49	 * @param callback - called on every change.
281	    50	 * @returns the unsubscribe function.
282	    51	 */
283	    52	export function subscribeToStorage(callback: () => void): () => void {
284	    53	  window.addEventListener(CHANGE_EVENT, callback);
285	    54	  window.addEventListener("storage", callback);
286	    55	  return () => {
287	    56	    window.removeEventListener(CHANGE_EVENT, callback);
288	    57	    window.removeEventListener("storage", callback);
289	    58	  };
290	    59	}
291	    60	
292	    61	let cachedRaw: string | null = null;
293	    62	let cachedIds: string[] = [];
294	    63	
295	    64	/**
296	    65	 * Stable snapshot of the session ids (same array until the stored value changes),
297	    66	 * as useSyncExternalStore requires.
298	    67	 * @returns ids, newest first.
299	    68	 */
300	    69	export function sessionIdsSnapshot(): string[] {
301	    70	  const raw = typeof window === "undefined" ? null : window.localStorage.getItem(SESSIONS_KEY);
302	    71	  if (raw !== cachedRaw) {
303	    72	    cachedRaw = raw;
304	    73	    cachedIds = loadSessionIds();
305	    74	  }
306	    75	  return cachedIds;
307	    76	}
