348	     1	/**
349	     2	 * @module app/_lib/toolResults
350	     3	 *
351	     4	 * Picks the purposeful visuals for an answer (U3b) from the tool results the
352	     5	 * agent actually used — chosen by CODE, never by the LLM. Types come straight
353	     6	 * from the tool builders (single source of truth).
354	     7	 */
355	     8	import type { FinalAnswer } from "@/core/agent/answerSchema";
356	     9	import type { CompareHubsOutput } from "@/core/agent/tools/compareHubs";
357	    10	import type { ExplainHubScoreOutput } from "@/core/agent/tools/explainHubScore";
358	    11	import type { WeatherStatOutput } from "@/core/agent/tools/getWeatherStat";
359	    12	import type { RankHubsOutput } from "@/core/agent/tools/rankHubs";
360	    13	
361	    14	/** One visual to render under an answer. */
362	    15	export type AnswerVisual =
363	    16	  | { kind: "breakdown"; key: string; data: ExplainHubScoreOutput }
364	    17	  | { kind: "grid"; key: string; data: CompareHubsOutput }
365	    18	  | { kind: "seasonality"; key: string; data: WeatherStatOutput }
366	    19	  | { kind: "ranking"; key: string; data: RankHubsOutput };
367	    20	
368	    21	/** Most visuals shown under one answer (more becomes noise). */
369	    22	const MAX_VISUALS = 2;
370	    23	
371	    24	/** Order of usefulness when an answer used several tools. */
372	    25	const PRIORITY: AnswerVisual["kind"][] = ["grid", "breakdown", "seasonality", "ranking"];
373	    26	
374	    27	const KIND_BY_TOOL: Record<string, AnswerVisual["kind"]> = {
375	    28	  compare_hubs: "grid",
376	    29	  explain_hub_score: "breakdown",
377	    30	  get_weather_stat: "seasonality",
378	    31	  rank_hubs: "ranking",
379	    32	};
380	    33	
381	    34	/**
382	    35	 * Chooses up to two visuals from an answer's tool calls: skips failed calls and
383	    36	 * duplicates (same tool + input), keeps the most useful kinds first.
384	    37	 * @param answer - the validated answer.
385	    38	 * @returns the visuals to render.
386	    39	 */
387	    40	export function pickVisuals(answer: FinalAnswer): AnswerVisual[] {
388	    41	  if (answer.outOfScope) return [];
389	    42	  const seen = new Set<string>();
390	    43	  const visuals: AnswerVisual[] = [];
391	    44	  for (const call of answer.meta.toolCalls) {
392	    45	    const kind = KIND_BY_TOOL[call.tool];
393	    46	    const output = call.output as Record<string, unknown> | null;
394	    47	    if (!kind || !output || "error" in output) continue;
395	    48	    const key = `${call.tool}:${JSON.stringify(call.input)}`;
396	    49	    if (seen.has(key)) continue;
397	    50	    seen.add(key);
398	    51	    visuals.push({ kind, key, data: output } as AnswerVisual);
399	    52	  }
400	    53	  return visuals.sort((a, b) => PRIORITY.indexOf(a.kind) - PRIORITY.indexOf(b.kind)).slice(0, MAX_VISUALS);
401	    54	}
