62	    61	async function readEvents(response: Response, onEvent: (event: SuiteEvent | { type: "error"; message: string }) => void): Promise<void> {
63	    62	  const reader = response.body!.pipeThrough(new TextDecoderStream()).getReader();
64	    63	  let buffer = "";
65	    64	  for (;;) {
66	    65	    const { value, done } = await reader.read();
67	    66	    if (done) break;
68	    67	    buffer += value;
69	    68	    const lines = buffer.split("\n");
70	    69	    buffer = lines.pop() ?? "";
71	    70	    for (const line of lines) if (line.trim()) onEvent(JSON.parse(line));
72	    71	  }
73	    72	}
