544	   100	    .replace(/[*_`#>]+/g, "") // emphasis, code, headings, quotes
545	   101	    .replace(/^\s*[-•]\s+/gm, "") // list bullets
546	   102	    .replace(/≥\s*/g, "at least ")
547	   103	    .replace(/≤\s*/g, "at most ")
548	   104	    .replace(/(\d)\s*–\s*(\d)/g, "$1 to $2") // ranges use an en dash: 0–100 → 0 to 100 (dates like 2021-01-01 stay intact)
549	   105	    .replace(/\s*→\s*/g, " to ")
550	   106	    .replace(/\s*·\s*/g, ", ")
551	   107	    .replace(/\s*\n+\s*/g, ". ")
552	   108	    .replace(/\.\s*\./g, ".")
