    51	 * @param request - the validated request.
    52	 * @param run - runs the turn and reports progress through callbacks.
    53	 * @returns a stream of UI message chunks.
    54	 */
    55	export function buildChatStream(request: ChatRequest, run: TurnRunner) {
    56	  return createUIMessageStream<SneakoscopeUIMessage>({
    57	    execute: async ({ writer }) => {
    58	      writer.write({ type: "start" });
    59	      // Running calls by the SDK's call id (parallel calls to one tool stay apart). Without an id
    60	      // (tests, older callers) they're matched first-in-first-out per tool name.
    61	      const pending = new Map<string, { id: string; label: string }[]>();
    62	      const key = (tool: string, callId?: string) => callId ?? `tool:${tool}`;
    63	      let callCount = 0;
    64	      let textId: string | null = null;
    65	      let attempt = 0;
    66	
    67	      /** Closes the open answer-text part, if any (a new attempt or a restart opens a fresh one). */
    68	      const endText = () => {
    69	        if (textId) writer.write({ type: "text-end", id: textId });
    70	        textId = null;
    71	      };
    72	
    73	      try {
    74	        const result = await run(request, {
    75	          onSession: (sessionId) => writer.write({ type: "data-session", id: "session", data: { sessionId } }),
    76	          onToolStart: (tool, input, callId, label) => {
    77	            const call = { id: `progress-${++callCount}`, label: label ?? progressLabel(tool, input) };
    78	            pending.set(key(tool, callId), [...(pending.get(key(tool, callId)) ?? []), call]);
    79	            writer.write({ type: "data-progress", id: call.id, data: { tool, label: call.label, status: "running" } });
    80	          },
    81	          onToolEnd: (tool, output, callId) => {
    82	            const call = pending.get(key(tool, callId))?.shift();
    83	            if (!call) return;
    84	            const failed = !!output && typeof output === "object" && "error" in output;
    85	            writer.write({ type: "data-progress", id: call.id, data: { tool, label: call.label, status: failed ? "failed" : "done" } });
    86	          },
    87	          onAnswerDelta: (delta) => {
    88	            if (!textId) {
    89	              textId = `answer-${attempt}`;
    90	              writer.write({ type: "text-start", id: textId });
    91	            }
    92	            writer.write({ type: "text-delta", id: textId, delta });
    93	          },
    94	          // The model started its answer text over: the UI shows the newest text part, so open a new one.
    95	          onAnswerRestart: () => {
    96	            endText();
    97	            attempt++;
    98	          },
    99	          onRetry: () => {
   100	            endText();
   101	            attempt++;
   102	            writer.write({ type: "data-retry", id: `retry-${attempt}`, data: { message: RETRY_MESSAGE } });
   103	          },
   104	        });
   105	        endText();
   106	        writer.write({ type: "data-answer", id: "answer", data: result.answer });
   107	      } catch (error) {
   108	        endText();
   109	        console.error(boundaryLogLine(error, "buildChatStream", "apiRoute"));
   110	        const { code, message, hint, retryable } = toUserError(error);
   111	        writer.write({ type: "data-error", id: "error", data: { code, message, hint, retryable } });
   112	      }
   113	      writer.write({ type: "finish" });
   114	    },
   115	    onError: (error) => toUserError(error).message,
   116	  });
   117	}
