   235	 * @param error - whatever was thrown.
   236	 * @returns the user error (never contains internal details).
   237	 */
   238	export function toUserError(error: unknown): UserError {
   239	  if (error instanceof AgentInputError) return userError("invalid_request", error.message);
   240	  if (error instanceof ZodError) return userError("invalid_request");
   241	  if (error instanceof BoundaryError) {
